\title{Strong Divisibility Sequences as Lattice Homomorphisms:\\
Finitary Meet/Join Laws and Coprimality Propagation}
\author{Aristotle}
\date{2026-06-18}

\begin{document}
\maketitle

\begin{abstract}
A \emph{strong divisibility sequence} is a sequence $a:\N\to\N$ satisfying $a(0)=0$ and the meet law
$\gcd(a(m),a(n))=a(\gcd(m,n))$. This single identity is the structure shared by the Fibonacci numbers,
the Mersenne/repunit sequences $b^n-1$, and the identity sequence. We develop the \emph{order-theoretic}
side of these axioms: a strong divisibility sequence is precisely an inf-homomorphism and
sup-semihomomorphism of the divisibility lattice $(\N,\divides,\gcd,\lcm)$. We establish (i) the binary
join sub-law $\lcm(a(m),a(n))\divides a(\lcm(m,n))$, derived purely from divisibility monotonicity;
(ii) coprimality propagation, governed by the single boundary condition $a(1)=1$, including the collapse
$\gcd(a(m),a(n))=a(1)$ for coprime indices; (iii) the finitary generalizations of both laws --- the meet
law as an exact equality over arbitrary finite families and the join law as a divisibility; and (iv) a
product law for pairwise-coprime indices. The recurring phenomenon is a structural asymmetry: meet is
preserved \emph{exactly}, while join is preserved only \emph{up to divisibility}. Specializing to the
Fibonacci and Mersenne instances yields cross-domain corollaries, including coprimality of Fibonacci
numbers at coprime indices and the residual identity $\gcd(b^m-1,b^n-1)=b-1=a(1)$ for coprime $m,n$.
All results are fully machine-verified.
\end{abstract}

\section{Introduction}

\subsection{Motivation}
Two classical families of integer sequences exhibit a striking gcd-transport property. The Fibonacci
numbers $F_n$ satisfy $\gcd(F_m,F_n)=F_{\gcd(m,n)}$, and the Mersenne numbers satisfy
$\gcd(b^m-1,b^n-1)=b^{\gcd(m,n)}-1$. Historically each family carried its own theory of ranks of
apparition (entry points) and primitive divisors --- for Fibonacci through Carmichael's theorem, for
$b^n-1$ through Zsygmondy's theorem. These theories share a common algebraic backbone, captured by the
notion of a \emph{strong divisibility sequence}. The key observation is that the defining axiom is not
merely an arithmetic identity but a lattice-homomorphism property: the natural numbers under
divisibility form a lattice with meet $\gcd$ and join $\lcm$, and the axiom states that $a$ preserves
the meet.

\subsection{Contributions}
\begin{enumerate}[label=(\arabic*)]
  \item Binary join sub-law (\texttt{lcm\_dvd\_index}): $\lcm(a(m),a(n))\divides a(\lcm(m,n))$.
  \item Coprimality collapse and propagation (\texttt{gcd\_indices\_coprime}, \texttt{coprime\_of\_coprime}).
  \item Finitary meet law (\texttt{finset\_gcd\_eq}): exact equality over finite families.
  \item Finitary join sub-law (\texttt{finset\_lcm\_dvd}): divisibility over finite families.
  \item Pairwise coprimality and product law (\texttt{pairwise\_coprime}, \texttt{prod\_dvd\_index}).
  \item Cross-domain corollaries for Fibonacci and Mersenne sequences.
\end{enumerate}
The unifying theme is the meet/join asymmetry: an exact equality for $\gcd$, a one-directional
divisibility for $\lcm$, visible uniformly at every arity.

\section{Definitions and basic structure}

\begin{definition}[Strong divisibility sequence]
A \emph{strong divisibility sequence} is a function $a:\N\to\N$ with
\begin{itemize}
  \item[(Z)] $a(0)=0$;
  \item[(M)] $\gcd(a(m),a(n))=a(\gcd(m,n))$ for all $m,n\in\N$.
\end{itemize}
\end{definition}

\begin{definition}[Divisibility lattice]
The set $\N$ ordered by $x\preceq y :\iff x\divides y$ is a lattice with meet $\gcd$, join $\lcm$,
bottom $1$, and top $0$. Axiom (M) states that $a$ is a meet-homomorphism.
\end{definition}

\begin{lemma}[Divisibility monotonicity, \texttt{dvd\_of\_dvd}]\label{lem:mono}
If $m\divides n$ then $a(m)\divides a(n)$.
\end{lemma}
\begin{proof}[Proof sketch]
If $m\divides n$ then $\gcd(m,n)=m$, so by (M) $\gcd(a(m),a(n))=a(m)$. Since $\gcd(a(m),a(n))\divides a(n)$,
we get $a(m)\divides a(n)$.
\end{proof}

\begin{lemma}[Meet bridge, \texttt{dvd\_gcd\_iff}]
For all $d,m,n$: $d\divides a(\gcd(m,n))\iff d\divides a(m)\wedge d\divides a(n)$.
\end{lemma}
\begin{proof}[Proof sketch]
Rewrite $a(\gcd(m,n))=\gcd(a(m),a(n))$ by (M); apply $d\divides\gcd(x,y)\iff d\divides x\wedge d\divides y$.
\end{proof}

\section{The binary lattice laws}

\begin{theorem}[Coprime collapse, \texttt{gcd\_indices\_coprime}]\label{thm:collapse}
If $\gcd(m,n)=1$ then $\gcd(a(m),a(n))=a(1)$.
\end{theorem}
\begin{proof}[Proof sketch]
By (M), $\gcd(a(m),a(n))=a(\gcd(m,n))=a(1)$.
\end{proof}

\begin{theorem}[Coprimality propagation, \texttt{coprime\_of\_coprime}]\label{thm:prop}
If $a(1)=1$ and $\gcd(m,n)=1$, then $\gcd(a(m),a(n))=1$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:collapse}, $\gcd(a(m),a(n))=a(1)=1$.
\end{proof}

\begin{theorem}[Binary join sub-law, \texttt{lcm\_dvd\_index}]\label{thm:joinbin}
For all $m,n$: $\lcm(a(m),a(n))\divides a(\lcm(m,n))$.
\end{theorem}
\begin{proof}[Proof sketch]
By Lemma~\ref{lem:mono} applied to $m\divides\lcm(m,n)$ and $n\divides\lcm(m,n)$, both $a(m)$ and $a(n)$
divide $a(\lcm(m,n))$. The universal property $\lcm(x,y)\divides z\iff x\divides z\wedge y\divides z$ then
gives the claim. The proof uses only monotonicity, not (M) directly, which is why join is preserved only
up to divisibility. For example $\lcm(F_4,F_6)=24$ while $F_{12}=144$, and $24\divides 144$ strictly.
\end{proof}

\section{Finitary lattice laws}

\begin{theorem}[Finitary meet law, \texttt{finset\_gcd\_eq}]\label{thm:fgcd}
For any finite index set $t$ and $g:\iota\to\N$,
\[
\gcd_{i\in t} a(g(i)) = a\Big(\gcd_{i\in t} g(i)\Big).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $t$. Empty case: both sides are $0$ (by $a(0)=0$). Insert step for $t'=\{c\}\cup t$: expand
with $\gcd$-insert, apply the induction hypothesis, transport $\gcd$ to $\Z$-style $\gcd$ via the
normalization bridge, then apply (M).
\end{proof}

\begin{theorem}[Finitary join sub-law, \texttt{finset\_lcm\_dvd}]\label{thm:flcm}
For any finite index set $t$ and $g:\iota\to\N$,
\[
\lcm_{i\in t} a(g(i)) \divides a\Big(\lcm_{i\in t} g(i)\Big).
\]
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $t$. Empty case: $\lcm$ of the empty family is $1$, which divides everything. Insert step:
expand with $\lcm$-insert and apply $\lcm\text{-}dvd$; each argument divides the target by
Lemma~\ref{lem:mono} (first argument) and by chaining the induction hypothesis with
Lemma~\ref{lem:mono} (second argument).
\end{proof}

\section{Pairwise coprimality and the product law}

\begin{theorem}[Pairwise coprimality, \texttt{pairwise\_coprime}]\label{thm:pair}
If $a(1)=1$ and the indices $\{g(i):i\in t\}$ are pairwise coprime, then the values $\{a(g(i)):i\in t\}$
are pairwise coprime.
\end{theorem}
\begin{proof}[Proof sketch]
For distinct $i,j$, $\gcd(g(i),g(j))=1$, so Theorem~\ref{thm:prop} gives $\gcd(a(g(i)),a(g(j)))=1$.
\end{proof}

\begin{theorem}[Coprime-index product law, \texttt{prod\_dvd\_index}]\label{thm:prod}
If $a(1)=1$ and the indices are pairwise coprime, then
\[
\prod_{i\in t} a(g(i)) \divides a\Big(\prod_{i\in t} g(i)\Big).
\]
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:pair} the factors are pairwise coprime. In the decomposition monoid $\N$, pairwise
coprimality (via $\mathrm{IsRelPrime}$) upgrades the family of divisibilities $a(g(i))\divides a(\prod g)$
(each from Lemma~\ref{lem:mono}) into a divisibility of the product.
\end{proof}

\begin{remark}
The ring-theoretic $\mathrm{IsCoprime}$ is strictly stronger than $\mathrm{Nat.Coprime}$ on $\N$; the
product law is routed through $\mathrm{IsRelPrime}$, using that $\N$ is a decomposition monoid.
\end{remark}

\section{Cross-domain corollaries}

\paragraph{Instances.} Fibonacci ($a=F$, with $F_1=1$); Mersenne ($a(n)=b^n-1$, with $a(1)=b-1$);
identity ($a(n)=n$).

\begin{corollary}[\texttt{fib\_coprime\_of\_coprime}]
If $\gcd(m,n)=1$ then $\gcd(F_m,F_n)=1$.
\end{corollary}
\begin{corollary}[\texttt{fib\_lcm\_dvd}]
$\lcm(F_m,F_n)\divides F_{\lcm(m,n)}$.
\end{corollary}
\begin{corollary}[\texttt{fib\_finset\_gcd}]
$\gcd_{i\in t} F_{g(i)} = F_{\gcd_{i\in t} g(i)}$.
\end{corollary}
\begin{corollary}[\texttt{fib\_finset\_lcm\_dvd}]
$\lcm_{i\in t} F_{g(i)} \divides F_{\lcm_{i\in t} g(i)}$.
\end{corollary}
\begin{corollary}[\texttt{fib\_prod\_dvd}]
For pairwise-coprime indices, $\prod_{i} F_{g(i)} \divides F_{\prod_i g(i)}$.
\end{corollary}
\begin{corollary}[\texttt{mersenne\_gcd\_coprime}]
If $\gcd(m,n)=1$ then $\gcd(b^m-1,b^n-1)=b-1$.
\end{corollary}
\noindent The residual $b-1$ is precisely $a(1)$, the image of the lattice bottom, explaining why
coprimality of values fails for $b>2$.

\section{Algorithms}
\paragraph{Finitary meet/join verifier.} Given $a$ and indices $g_1,\dots,g_k$, check
$\gcd_i a(g_i)=a(\gcd_i g_i)$ and $\lcm_i a(g_i)\divides a(\lcm_i g_i)$. Complexity
$O(k\log M)$ integer operations plus the cost of evaluating $a$.
\paragraph{Coprime-index product checker.} Verify pairwise coprimality in $O(k^2)$ gcd computations,
then check $\prod_i a(g_i)\divides a(\prod_i g_i)$ and report the cofactor.

\section{Applications}
Unified primitive-divisor theory (Carmichael and Zsygmondy under one roof); fast coprimality
certificates for Fibonacci numbers without factoring; divisor-lattice analysis of recurrence sequences.

\section{Discussion}
The central phenomenon is the meet/join asymmetry: $a$ is an exact inf-homomorphism but only a
sup-semihomomorphism of $(\N,\divides)$. This traces to the meet law being axiomatic while the join law is
a consequence of monotonicity, which can only place the join of images below the image of the join. The
lattice bottom $1$ governs coprimality: it propagates exactly when $a(1)=1$, and the residual otherwise is
always $a(1)$.

\section{Future directions}
\begin{enumerate}[label=(\arabic*)]
  \item \textbf{Multiplicative-order bridge.} For $b\ge 2$ and prime $p\nmid b$, the Mersenne entry point
  should equal $\orderof(b\bmod p)$ in $(\Z/p\Z)^\times$.
  \item \textbf{Lucas U-sequences.} For coprime $P,Q$, $U_n(P,Q)$ is a strong divisibility sequence with
  $U_1=1$, so all results transfer to Pell, Jacobsthal, and the Lucas family at once.
  \item \textbf{Sharp join law.} For Fibonacci, $\lcm(F_m,F_n)=F_{\lcm(m,n)}$ iff $m\divides n$ or
  $n\divides m$, quantifying the failure of sup-homomorphism.
  \item \textbf{Product equality up to residual.} When $a(1)=1$ and indices are pairwise coprime,
  $\prod a(g(i))$ should equal the primitive-part radical of $a(\prod g(i))$.
\end{enumerate}

\section{Conclusion}
A strong divisibility sequence is a single morphism of the divisibility lattice: exact on meets,
sub-homomorphic on joins. From the two axioms $a(0)=0$ and $\gcd(a(m),a(n))=a(\gcd(m,n))$ flow
monotonicity, an exact finitary meet law, a divides-only finitary join law, coprimality propagation gated
by $a(1)=1$, and a coprime-index product law --- uniformly for Fibonacci, Mersenne, repunit, and identity
sequences.

\end{document}

